import{_ as t,c as n,o as a,ae as s}from"./chunks/framework.Cd-3tpCq.js";const u=JSON.parse('{"title":"Reporting — Overview (GraphQL)","description":"","frontmatter":{"outline":false,"examples":[{"id":"gql-overview-total-sales","title":"Total Sales","description":"Total revenue for the period (default `type`). Carries a previous-vs-current comparison plus a per-day `over_time` series for charting.","query":"query AdminReportingOverview($type: String, $start: String, $end: String, $channel: String) {\\n  statsAdminReportingOverview(type: $type, start: $start, end: $end, channel: $channel) {\\n    entity\\n    type\\n    dateRange\\n    statistics\\n  }\\n}\\n","variables":"{\\n  \\"type\\": \\"total-sales\\",\\n  \\"start\\": \\"2026-05-10\\",\\n  \\"end\\": \\"2026-06-09\\",\\n  \\"channel\\": \\"default\\"\\n}\\n","response":"{\\n  \\"data\\": {\\n    \\"statsAdminReportingOverview\\": {\\n      \\"entity\\": \\"overview\\",\\n      \\"type\\": \\"total-sales\\",\\n      \\"dateRange\\": { \\"previous\\": \\"10 Apr 2026 - 10 May 2026\\", \\"current\\": \\"10 May 2026 - 09 Jun 2026\\" },\\n      \\"statistics\\": {\\n        \\"sales\\": {\\n          \\"previous\\": 27243.5,\\n          \\"current\\": 9697.53,\\n          \\"formatted_total\\": \\"$9,697.53\\",\\n          \\"progress\\": -64.32\\n        },\\n        \\"over_time\\": {\\n          \\"previous\\": [\\n            { \\"label\\": \\"10 Apr\\", \\"total\\": 4200, \\"count\\": 6 },\\n            { \\"label\\": \\"11 Apr\\", \\"total\\": 1875.5, \\"count\\": 3 }\\n          ],\\n          \\"current\\": [\\n            { \\"label\\": \\"10 May\\", \\"total\\": 8500, \\"count\\": 12 },\\n            { \\"label\\": \\"11 May\\", \\"total\\": 1197.53, \\"count\\": 4 }\\n          ]\\n        }\\n      }\\n    }\\n  }\\n}\\n"},{"id":"gql-overview-total-orders","title":"Total Orders","description":"Number of orders placed in the period. Same previous-vs-current shape as Total Sales, with an integer `over_time` series.","query":"query AdminReportingOverview($type: String, $start: String, $end: String, $channel: String) {\\n  statsAdminReportingOverview(type: $type, start: $start, end: $end, channel: $channel) {\\n    entity\\n    type\\n    dateRange\\n    statistics\\n  }\\n}\\n","variables":"{\\n  \\"type\\": \\"total-orders\\",\\n  \\"start\\": \\"2026-05-10\\",\\n  \\"end\\": \\"2026-06-09\\",\\n  \\"channel\\": \\"default\\"\\n}\\n","response":"{\\n  \\"data\\": {\\n    \\"statsAdminReportingOverview\\": {\\n      \\"entity\\": \\"overview\\",\\n      \\"type\\": \\"total-orders\\",\\n      \\"dateRange\\": { \\"previous\\": \\"10 Apr 2026 - 10 May 2026\\", \\"current\\": \\"10 May 2026 - 09 Jun 2026\\" },\\n      \\"statistics\\": {\\n        \\"orders\\": {\\n          \\"previous\\": 41,\\n          \\"current\\": 58,\\n          \\"progress\\": 41.46\\n        },\\n        \\"over_time\\": {\\n          \\"previous\\": [\\n            { \\"label\\": \\"10 Apr\\", \\"total\\": 6, \\"count\\": 6 },\\n            { \\"label\\": \\"11 Apr\\", \\"total\\": 3, \\"count\\": 3 }\\n          ],\\n          \\"current\\": [\\n            { \\"label\\": \\"10 May\\", \\"total\\": 12, \\"count\\": 12 },\\n            { \\"label\\": \\"11 May\\", \\"total\\": 4, \\"count\\": 4 }\\n          ]\\n        }\\n      }\\n    }\\n  }\\n}\\n"},{"id":"gql-overview-total-customers","title":"Total Customers","description":"Number of new customers registered in the period. Note the `over_time` rows carry only `label` and `total` — no `count`.","query":"query AdminReportingOverview($type: String, $start: String, $end: String, $channel: String) {\\n  statsAdminReportingOverview(type: $type, start: $start, end: $end, channel: $channel) {\\n    entity\\n    type\\n    dateRange\\n    statistics\\n  }\\n}\\n","variables":"{\\n  \\"type\\": \\"total-customers\\",\\n  \\"start\\": \\"2026-05-10\\",\\n  \\"end\\": \\"2026-06-09\\",\\n  \\"channel\\": \\"default\\"\\n}\\n","response":"{\\n  \\"data\\": {\\n    \\"statsAdminReportingOverview\\": {\\n      \\"entity\\": \\"overview\\",\\n      \\"type\\": \\"total-customers\\",\\n      \\"dateRange\\": { \\"previous\\": \\"10 Apr 2026 - 10 May 2026\\", \\"current\\": \\"10 May 2026 - 09 Jun 2026\\" },\\n      \\"statistics\\": {\\n        \\"customers\\": {\\n          \\"previous\\": 18,\\n          \\"current\\": 25,\\n          \\"progress\\": 38.89\\n        },\\n        \\"over_time\\": {\\n          \\"previous\\": [\\n            { \\"label\\": \\"10 Apr\\", \\"total\\": 2 },\\n            { \\"label\\": \\"11 Apr\\", \\"total\\": 1 }\\n          ],\\n          \\"current\\": [\\n            { \\"label\\": \\"10 May\\", \\"total\\": 4 },\\n            { \\"label\\": \\"11 May\\", \\"total\\": 3 }\\n          ]\\n        }\\n      }\\n    }\\n  }\\n}\\n"},{"id":"gql-overview-top-selling-products-by-revenue","title":"Top Selling Products by Revenue","description":"Up to ~5 best-selling products by revenue. Here `statistics` is a flat array of product rows (no previous-vs-current shape), each carrying a nested `images` array.","query":"query AdminReportingOverview($type: String, $start: String, $end: String, $channel: String) {\\n  statsAdminReportingOverview(type: $type, start: $start, end: $end, channel: $channel) {\\n    entity\\n    type\\n    dateRange\\n    statistics\\n  }\\n}\\n","variables":"{\\n  \\"type\\": \\"top-selling-products-by-revenue\\",\\n  \\"start\\": \\"2026-05-10\\",\\n  \\"end\\": \\"2026-06-09\\",\\n  \\"channel\\": \\"default\\"\\n}\\n","response":"{\\n  \\"data\\": {\\n    \\"statsAdminReportingOverview\\": {\\n      \\"entity\\": \\"overview\\",\\n      \\"type\\": \\"top-selling-products-by-revenue\\",\\n      \\"dateRange\\": { \\"previous\\": \\"10 Apr 2026 - 10 May 2026\\", \\"current\\": \\"10 May 2026 - 09 Jun 2026\\" },\\n      \\"statistics\\": [\\n        {\\n          \\"id\\": 2359,\\n          \\"name\\": \\"Horizon Arc 49\\\\\\" OLED Curved Gaming Monitor\\",\\n          \\"price\\": 4000,\\n          \\"formatted_price\\": \\"$3,899.00\\",\\n          \\"revenue\\": 38990,\\n          \\"formatted_revenue\\": \\"$38,990.00\\",\\n          \\"images\\": [\\n            {\\n              \\"id\\": 786,\\n              \\"type\\": \\"images\\",\\n              \\"path\\": \\"product/2359/Whw0RJrR1dLPn5HHkyk7G7hiUpY6aH8BFYOE7rlc.webp\\",\\n              \\"product_id\\": 2359,\\n              \\"position\\": 1,\\n              \\"url\\": \\"https://your-domain.com/storage/product/2359/Whw0RJrR1dLPn5HHkyk7G7hiUpY6aH8BFYOE7rlc.webp\\"\\n            }\\n          ],\\n          \\"progress\\": 12.5\\n        },\\n        {\\n          \\"id\\": 1804,\\n          \\"name\\": \\"Aurora Mesh Ergonomic Office Chair\\",\\n          \\"price\\": 520,\\n          \\"formatted_price\\": \\"$520.00\\",\\n          \\"revenue\\": 15600,\\n          \\"formatted_revenue\\": \\"$15,600.00\\",\\n          \\"images\\": [\\n            {\\n              \\"id\\": 612,\\n              \\"type\\": \\"images\\",\\n              \\"path\\": \\"product/1804/Kp3mZ8aQ1wXfR2tLvHsN4cYbE9dUoG7iMxPq0Jr.webp\\",\\n              \\"product_id\\": 1804,\\n              \\"position\\": 1,\\n              \\"url\\": \\"https://your-domain.com/storage/product/1804/Kp3mZ8aQ1wXfR2tLvHsN4cYbE9dUoG7iMxPq0Jr.webp\\"\\n            }\\n          ],\\n          \\"progress\\": -4.18\\n        }\\n      ]\\n    }\\n  }\\n}\\n"}]},"headers":[],"relativePath":"api/graphql-api/admin/reporting/overview.md","filePath":"api/graphql-api/admin/reporting/overview.md"}'),r={name:"api/graphql-api/admin/reporting/overview.md"};function i(o,e,d,l,c,p){return a(),n("div",null,e[0]||(e[0]=[s('<h1 id="reporting-—-overview-graphql" tabindex="-1">Reporting — Overview (GraphQL) <a class="header-anchor" href="#reporting-—-overview-graphql" aria-label="Permalink to &quot;Reporting — Overview (GraphQL)&quot;">​</a></h1><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>Query</strong></td><td><code>statsAdminReportingOverview</code></td></tr><tr><td><strong>Endpoint</strong></td><td><code>POST /api/admin/graphql</code></td></tr><tr><td><strong>Returns</strong></td><td>A single object: <code>{ entity, type, dateRange, statistics }</code></td></tr></tbody></table><p>All admin endpoints require an admin Bearer token — see <a href="/api/graphql-api/admin/authentication.html">Authentication</a>.</p><p>The Overview query returns a single headline figure across the whole store for the chosen <code>type</code>. It is an API convenience aggregation — there is <strong>no</strong> matching &quot;Overview&quot; screen in the admin panel (the admin Reporting menu goes straight to Sales / Customers / Products). Use it to fetch one top-line number without having to call the per-section queries.</p><h2 id="understanding-type-—-overview-is-four-separate-headlines" tabindex="-1">Understanding <code>type</code> — Overview is <strong>four</strong> separate headlines <a class="header-anchor" href="#understanding-type-—-overview-is-four-separate-headlines" aria-label="Permalink to &quot;Understanding `type` — Overview is **four** separate headlines&quot;">​</a></h2><p>A single call returns <strong>one</strong> headline. The <code>type</code> argument picks which:</p><ul><li><code>total-sales</code> (default) — total revenue for the period.</li><li><code>total-orders</code> — number of orders placed.</li><li><code>total-customers</code> — number of new customers registered.</li><li><code>top-selling-products-by-revenue</code> — the best-selling products by revenue.</li></ul><p>The <code>statistics</code> payload <strong>changes shape per <code>type</code></strong> — for the three comparison headlines it is an object with a previous-vs-current figure plus an <code>over_time</code> series; for <code>top-selling-products-by-revenue</code> it is a flat array of product rows. Always branch on <code>type</code> when consuming it.</p><p><code>total-sales</code> is the default — if you omit <code>type</code>, you get the total-revenue headline.</p><h2 id="arguments" tabindex="-1">Arguments <a class="header-anchor" href="#arguments" aria-label="Permalink to &quot;Arguments&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Argument</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>type</code></td><td><code>String</code></td><td>No</td><td>One of the four values above. Defaults to <code>total-sales</code>.</td></tr><tr><td><code>start</code></td><td><code>String</code> (YYYY-MM-DD)</td><td>No</td><td>Lower bound of the reporting window. Defaults to <strong>30 days ago</strong>.</td></tr><tr><td><code>end</code></td><td><code>String</code> (YYYY-MM-DD)</td><td>No</td><td>Upper bound. Defaults to <strong>today</strong>.</td></tr><tr><td><code>channel</code></td><td><code>String</code></td><td>No</td><td>Channel <strong>code</strong> (e.g. <code>default</code>) to scope the figures to a single storefront channel. Defaults to all channels.</td></tr></tbody></table><p><code>start</code> / <code>end</code> drive both the figures and the <code>previous</code> baseline used for each <code>progress</code> percentage — the previous period is the same-length window immediately before <code>start</code>.</p><h2 id="selection-set" tabindex="-1">Selection set <a class="header-anchor" href="#selection-set" aria-label="Permalink to &quot;Selection set&quot;">​</a></h2><div class="language-graphql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">graphql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">query</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> AdminReportingOverview</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">$type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">String</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">$start</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">String</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">$end</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">String</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">$channel</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">String</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) {</span></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">  statsAdminReportingOverview</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">$type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">start</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">$start</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">end</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">$end</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">channel</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">$channel</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) {</span></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">    entity</span></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">    type</span></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">    dateRange</span></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">    statistics</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><ul><li><code>entity</code> — always <code>&quot;overview&quot;</code>.</li><li><code>type</code> — echoes back the requested headline.</li><li><code>dateRange</code> — an <strong>object</strong> <code>{ previous, current }</code> naming the two comparison windows. <code>current</code> is the window you asked for; <code>previous</code> is the equal-length window immediately before it. This field resolves correctly over GraphQL.</li><li><code>statistics</code> — a JSON scalar whose shape depends on <code>type</code> (documented below). Query it bare — no sub-selection.</li></ul><p>Figures with a <code>previous</code> / <code>current</code> / <code>progress</code> shape are period comparisons: <code>current</code> is the chosen window, <code>previous</code> is the preceding window of equal length, and <code>progress</code> is the percentage change (can be negative).</p><div class="tip custom-block"><p class="custom-block-title">No View Details, no Export</p><p>Unlike the Sales / Customers / Products queries, the Overview query has <strong>no View Details and no Export</strong> — it is a top-line summary only. Reporting requires only authentication; there is no permission gate.</p></div><h2 id="response-shapes-by-type" tabindex="-1">Response shapes by <code>type</code> <a class="header-anchor" href="#response-shapes-by-type" aria-label="Permalink to &quot;Response shapes by `type`&quot;">​</a></h2><h3 id="total-sales" tabindex="-1"><code>total-sales</code> <a class="header-anchor" href="#total-sales" aria-label="Permalink to &quot;`total-sales`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Key</th><th>Shape</th><th>Meaning</th></tr></thead><tbody><tr><td><code>sales</code></td><td><code>{ previous, current, formatted_total, progress }</code></td><td>Gross sales in the window; <code>formatted_total</code> is the current value in base currency.</td></tr><tr><td><code>over_time</code></td><td><code>{ previous, current }</code> — each an array of <code>{ label, total, count }</code></td><td>One bucket <strong>per day</strong> for the chart line, given for both the previous and current windows. <code>total</code> is sales, <code>count</code> is order count.</td></tr></tbody></table><h3 id="total-orders" tabindex="-1"><code>total-orders</code> <a class="header-anchor" href="#total-orders" aria-label="Permalink to &quot;`total-orders`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Key</th><th>Shape</th><th>Meaning</th></tr></thead><tbody><tr><td><code>orders</code></td><td><code>{ previous, current, progress }</code></td><td>Orders placed in the window.</td></tr><tr><td><code>over_time</code></td><td><code>{ previous, current }</code> — each an array of <code>{ label, total, count }</code></td><td>One bucket per day for both windows. <code>total</code> is the order count for the day; <code>count</code> mirrors it.</td></tr></tbody></table><h3 id="total-customers" tabindex="-1"><code>total-customers</code> <a class="header-anchor" href="#total-customers" aria-label="Permalink to &quot;`total-customers`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Key</th><th>Shape</th><th>Meaning</th></tr></thead><tbody><tr><td><code>customers</code></td><td><code>{ previous, current, progress }</code></td><td>New customers registered in the window.</td></tr><tr><td><code>over_time</code></td><td><code>{ previous, current }</code> — each an array of <code>{ label, total }</code></td><td>One bucket per day for both windows.</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title"><code>over_time</code> rows differ for customers</p><p>For <code>total-customers</code>, the <code>over_time</code> rows carry only <code>label</code> and <code>total</code> — there is <strong>no</strong> <code>count</code> field (unlike <code>total-sales</code> / <code>total-orders</code>).</p></div><h3 id="top-selling-products-by-revenue" tabindex="-1"><code>top-selling-products-by-revenue</code> <a class="header-anchor" href="#top-selling-products-by-revenue" aria-label="Permalink to &quot;`top-selling-products-by-revenue`&quot;">​</a></h3><p><code>statistics</code> is a flat <strong>array</strong> (up to ~5 rows) — there is no previous-vs-current wrapper. Each row: <code>id</code>, <code>name</code>, <code>price</code>, <code>formatted_price</code>, <code>revenue</code>, <code>formatted_revenue</code>, <code>images</code> (array of <code>{ id, type, path, product_id, position, url }</code>), and <code>progress</code> (the row&#39;s change vs. the previous window, can be negative).</p><h2 id="errors" tabindex="-1">Errors <a class="header-anchor" href="#errors" aria-label="Permalink to &quot;Errors&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Condition</th><th>Result</th></tr></thead><tbody><tr><td>Missing / invalid Bearer token</td><td><code>401 Unauthenticated</code></td></tr></tbody></table><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="/api/rest-api/admin/reporting/overview.html">Reporting — Overview (REST)</a> — same data over <code>GET /api/admin/reporting/stats</code>.</li><li><a href="/api/graphql-api/admin/dashboard/stats.html">Dashboard Statistics</a> — the headline cards behind the admin Dashboard screen.</li></ul>',31)]))}const g=t(r,[["render",i]]);export{u as __pageData,g as default};
